    'home.faq_q1': 'Thủ tục thuê xe tự lái tại Nha Trang Car cần chuẩn bị những gì?',
    'home.faq_a1': 'Quý khách chỉ cần: 1. Căn cước công dân (CCCD gắn chip) hoặc Hộ chiếu (Passport); 2. Giấy phép lái xe (GPLX hạng B1/B2/B đối với ô tô, A1/A đối với xe máy; riêng xe máy điện được MIỄN BẰNG LÁI 100%); 3. Khoản tiền cọc bảo đảm hợp đồng, cam kết hoàn trả 100% ngay khi kết thúc bàn giao xe trong 5 phút.',
    'home.faq_q2': 'Quy tắc tính thời gian thuê xe tại Nha Trang Car như thế nào?',
    'home.faq_a2': 'Nha Trang Car áp dụng quy tắc rõ ràng: Thuê theo ngày tính trọn vẹn 24 giờ kể từ thời điểm nhận xe thực tế (làm tròn lên ngày kế tiếp nếu quá giờ quy định). Thuê theo giờ tính làm tròn lên số giờ thực tế, tối thiểu 1 giờ. Chúng tôi không tự ý hoán đổi giữa các gói để luôn đảm bảo quyền lợi tốt nhất cho khách hàng.',
    'home.faq_q3': 'Chính sách hủy đơn đặt xe và hoàn tiền cọc giữ chỗ ra sao?',
    'home.faq_a3': 'Hủy trước 24 giờ so với giờ nhận xe sẽ được hoàn trả 100% tiền cọc giữ chỗ qua chuyển khoản. Hủy trong vòng 24 giờ sẽ áp dụng phí xử lý giữ xe theo quy chế của cửa hàng.',
