    'guide.faq_title': 'Câu hỏi thường gặp về quy trình thuê xe',
    'guide.faq_desc': 'Giải đáp chi tiết về giao nhận đêm, hủy chuyến, giữ giấy tờ và xử lý sự cố',
    'guide.faq_q1': 'Tôi hạ cánh chuyến bay đêm muộn tại Sân bay Cam Ranh (sau 22:00) thì có nhận xe được không?',
    'guide.faq_a1': 'Hoàn toàn được! Nha Trang Car hỗ trợ giao xe 24/7 tại ga đến Sân bay Quốc tế Cam Ranh. Quý khách chỉ cần cung cấp mã chuyến bay khi đặt xe trên web, nhân viên điều phối sẽ theo dõi giờ hạ cánh thực tế và chờ đón quý khách với biển tên tại sảnh đến mà không phát sinh thêm phụ phí đêm.',
    'guide.faq_q2': 'Nếu hãng hàng không đổi giờ bay hoặc tôi hủy chuyến thì tiền cọc 20% xử lý thế nào?',
    'guide.faq_a2': 'Quý khách hoàn toàn an tâm! Nha Trang Car cam kết hoàn trả 100% tiền cọc giữ chỗ qua chuyển khoản 24/7 nếu quý khách thông báo hủy trước 24 giờ so với giờ nhận xe. Trong trường hợp hoãn chuyến bay (delay), cửa hàng sẽ tự động dời giờ giao xe theo giờ hạ cánh mới hoàn toàn miễn phí.',
    'guide.faq_q3': 'Cửa hàng có giữ lại CCCD hoặc Hộ chiếu (Passport) bản gốc của tôi không?',
    'guide.faq_a3': 'Tuyệt đối KHÔNG giữ giấy tờ gốc! Nha Trang Car tuân thủ chính sách tôn trọng quyền riêng tư du khách. Nhân viên giao xe chỉ chụp ảnh scan đối chiếu tại chỗ và hoàn trả ngay lập tức tất cả giấy tờ tùy thân gốc (CCCD gắn chip / VNeID mức 2 / Passport) cho quý khách.',
    'guide.faq_q4': 'Khi trả xe thì tiền cọc trách nhiệm được hoàn trả như thế nào và mất bao lâu?',
    'guide.faq_a4': 'Quy trình hoàn cọc diễn ra siêu tốc chỉ từ 3 đến 5 phút. Ngay khi nhân viên kiểm tra xe theo biên bản số ban đầu, nếu xe nguyên vẹn, cửa hàng sẽ hoàn trả dứt điểm 100% tiền cọc hợp đồng cho quý khách bằng hình thức Chuyển khoản VietQR 24/7 (tiền về tài khoản ngay lập tức) hoặc Tiền mặt theo yêu cầu của quý khách.',
    'guide.faq_q5': 'Nếu trong quá trình di chuyển xe bị thủng lốp hoặc gặp sự cố kỹ thuật thì xử lý ra sao?',
    'guide.faq_a5': 'Quý khách chỉ cần gọi ngay Hotline cứu hộ 24/7 (0905 888 999). Đội ngũ kỹ thuật viên lưu động của Nha Trang Car sẽ có mặt trong vòng 15 – 30 phút tại bất kỳ khu vực nào trong nội thành Nha Trang và tuyến đường Bãi Dài Cam Ranh để vá vỏ, kích bình hoặc đổi xe tương đương nếu cần, đảm bảo hành trình nghỉ dưỡng không bị gián đoạn.',
    'guide.faq_q6': 'Có giới hạn số kilomet (km) di chuyển trong ngày hay không?',
    'guide.faq_a6': 'Hoàn toàn không giới hạn km đối với xe máy và xe máy điện trong phạm vi Khánh Hòa. Ô tô tự lái áp dụng định mức cực kỳ thoải mái 300 - 350 km/ngày (thoải mái đi trọn vẹn Vịnh Vĩnh Hy, Dốc Lết hoặc vi vu thành phố Đà Lạt mà không lo phát sinh phụ phí).',
