    // Contact FAQ Accordion
    'contact.faq_badge': 'CÂU HỎI THƯỜNG GẶP KHI LIÊN HỆ',
    'contact.faq_title': 'Giải đáp thắc mắc liên hệ & Giao nhận xe',
    'contact.faq_desc': 'Những câu hỏi du khách thường quan tâm nhất khi liên hệ đặt xe và hỗ trợ tại DriveRent Nha Trang.',
    'contact.faq_q1': 'Tôi có thể liên hệ nhận xe tại Sân bay Cam Ranh vào ban đêm (sau 22:00) được không?',
    'contact.faq_a1': 'Hoàn toàn được. DriveRent có đội ngũ điều phối túc trực 24/7 tại ga đến Sân bay Quốc tế Cam Ranh. Quý khách chỉ cần cung cấp mã chuyến bay và giờ hạ cánh dự kiến, nhân viên sẽ chuẩn bị xe sẵn tại bãi đón sân bay.',
    'contact.faq_q2': 'Cửa hàng có hỗ trợ giao nhận xe tận sảnh khách sạn hoặc resort ở Nha Trang không?',
    'contact.faq_a2': 'Có, chúng tôi miễn phí 100% chi phí giao nhận xe tận nơi tại tất cả các khách sạn nội thành TP. Nha Trang và dọc trục đường biển Trần Phú đối với hợp đồng thuê từ 1 ngày trở lên.',
    'contact.faq_q3': 'Nếu xe gặp sự cố thủng lốp hoặc hỏng hóc trên cung đèo, tôi liên hệ hỗ trợ như thế nào?',
    'contact.faq_a3': 'Quý khách vui lòng gọi ngay Hotline cứu hộ 24/7 (0905 888 999). Đội xe kỹ thuật lưu động sẽ có mặt sau 15–25 phút để vá vỏ, kích bình hoặc điều xe đổi mới tận nơi hoàn toàn miễn phí nếu lỗi do kỹ thuật xe.',
    'contact.faq_q4': 'Khách du lịch quốc tế (Nga, Hàn Quốc, Anh) liên hệ đặt xe và tư vấn qua kênh nào thuận tiện nhất?',
    'contact.faq_a4': 'Du khách quốc tế có thể nhắn tin trực tiếp qua WhatsApp (+84 905 888 999) hoặc Zalo OA. Đội ngũ nhân viên thông thạo tiếng Anh, Nga và Hàn Quốc sẽ tư vấn chi tiết về bằng lái quốc tế IDP và quy định thuê xe.',
