    'reg.faq_header_title': 'Câu hỏi thường gặp về thủ tục thuê xe tại Nha Trang',
    'reg.faq_header_desc': 'Giải đáp nhanh mọi băn khoăn cho khách du lịch và gia đình',
    'reg.faq_q1': 'Du khách nước ngoài có thuê được Ô tô tự lái & Xe máy tại Nha Trang không?',
    'reg.faq_a1': 'Hoàn toàn được! Đối với Ô tô tự lái, quý khách chỉ cần Hộ chiếu và Bằng lái quốc tế IDP Vienna 1968 (kèm GPLX quốc gia gốc). Đối với Xe máy, quý khách có thể lái xe máy thông thường nếu có IDP Vienna Hạng A, hoặc ĐẶC BIỆT THUÊ XE MÁY ĐIỆN THÔNG MINH HOÀN TOÀN KHÔNG CẦN BẰNG LÁI (100% hợp pháp theo Luật Giao thông Việt Nam).',
    'reg.faq_q2': 'Xe máy điện thông minh & xe dưới 50cc có thực sự không cần bằng lái?',
    'reg.faq_a2': 'Chính xác 100%! Căn cứ Luật Giao thông Đường bộ Việt Nam, xe máy điện công suất động cơ dưới 4kW hoặc xe gắn máy dung tích xi-lanh dưới 50cc không yêu cầu Giấy phép lái xe. Người từ đủ 16 tuổi trở lên hoặc khách du lịch quốc tế đều được phép điều khiển tự do trên toàn bộ đường phố Nha Trang & Khánh Hòa.',
    'reg.faq_q3': 'Quy trình hoàn trả tiền cọc diễn ra như thế nào, có bị giữ cọc lâu không?',
    'reg.faq_a3': 'Nha Trang Car cam kết hoàn trả 100% tiền cọc hợp đồng ngay lập tức trong vòng 5 phút qua chuyển khoản ngân hàng ngay khi hoàn tất biên bản kiểm tra bàn giao xe. Chúng tôi nói KHÔNG với việc giữ cọc nhiều tuần hoặc trừ các chi phí vô lý.',
    'reg.faq_q4': 'Nếu không may xe gặp sự cố va quẹt hoặc thủng lốp dọc đường thì xử lý ra sao?',
    'reg.faq_a4': 'Tất cả Ô tô tự lái tại Nha Trang Car đều có gói Bảo hiểm thân vỏ 2 chiều 100%. Nếu có sự cố, quý khách chỉ cần giữ nguyên hiện trường, chụp ảnh và gọi ngay Hotline cứu hộ 24/7 của chúng tôi. Kỹ thuật viên sẽ có mặt hỗ trợ xử lý nhanh gọn và hỗ trợ xe thay thế tương đương.',
