    'home.faq_q1': 'What documents are required to rent a vehicle at Nha Trang Car?',
    'home.faq_a1': 'You only need: 1. National ID or Passport; 2. Valid driving license (Class B for cars, Class A for motorbikes; smart e-scooters are 100% LICENSE-FREE); 3. Contract security deposit, 100% refunded in 5 minutes upon vehicle return.',
