    'guide.faq_title': 'Frequently Asked Questions About Rental Process',
    'guide.faq_desc': 'Detailed answers on night delivery, flight cancellations, document policy, and roadside support',
    'guide.faq_q1': 'Can I receive the car if I land late at night at Cam Ranh Airport (after 22:00)?',
    'guide.faq_a1': 'Yes, absolutely! Nha Trang Car supports 24/7 delivery at Cam Ranh International Airport arrival hall. Simply provide your flight number when booking online; our dispatch team will track your flight live and welcome you with a nameboard with zero late-night surcharge.',
    'guide.faq_q2': 'How is my 20% deposit handled if my flight is rescheduled or cancelled?',
    'guide.faq_a2': 'Complete peace of mind! Nha Trang Car guarantees 100% refund of your booking deposit via 24/7 bank transfer if you cancel at least 24 hours prior to pickup. In case of flight delays, we automatically shift your pickup time to match your new landing time for free.',
    'guide.faq_q3': 'Does Nha Trang Car keep my original ID or Passport during rental?',
    'guide.faq_a3': 'Absolutely NOT! We strictly respect our customers privacy. Our delivery staff only takes a quick photo/scan on-site to verify records and immediately returns all your original documents (ID card, VNeID level 2, or Passport) on the spot.',
    'guide.faq_q4': 'How and when is the security deposit refunded upon vehicle return?',
    'guide.faq_a4': 'The refund is lightning-fast, taking just 3 to 5 minutes. As soon as our staff confirms vehicle condition against the initial 360° digital report, 100% of your security deposit is refunded on the spot via instant VietQR 24/7 or cash according to your preference.',
    'guide.faq_q5': 'What should I do if the vehicle has a flat tire or technical issue during the trip?',
    'guide.faq_a5': 'Simply call our 24/7 emergency rescue hotline (0905 888 999). Our mobile technical crew arrives within 15–30 minutes anywhere in Nha Trang and along Bai Dai Cam Ranh to patch tires, boost batteries, or swap vehicles if needed.',
    'guide.faq_q6': 'Is there a daily mileage (km) limit?',
    'guide.faq_a6': 'No limit at all for motorbikes and electric scooters within Khanh Hoa. For self-drive cars, we offer an ample allowance of 300 - 350 km/day (plenty for round trips to Vinh Hy Bay, Doc Let, or Da Lat without extra fees).',
