    // Contact FAQ Accordion
    'contact.faq_badge': 'FREQUENTLY ASKED QUESTIONS',
    'contact.faq_title': 'Contact & Vehicle Delivery Questions',
    'contact.faq_desc': 'Most common inquiries from travelers when contacting and booking vehicles at DriveRent Nha Trang.',
    'contact.faq_q1': 'Can I request vehicle pickup at Cam Ranh Airport late at night (after 22:00)?',
    'contact.faq_a1': 'Yes, absolutely. DriveRent has 24/7 dispatch staff at Cam Ranh International Airport arrivals. Simply provide your flight number and ETA; our staff will have your vehicle prepared outside the terminal.',
    'contact.faq_q2': 'Do you deliver vehicles directly to hotels or resorts in Nha Trang?',
    'contact.faq_a2': 'Yes, we provide 100% free delivery and collection to all hotels in central Nha Trang and along Tran Phu beach for rentals of 1 day or more.',
    'contact.faq_q3': 'What should I do if my vehicle has a puncture or breakdown on a mountain pass?',
    'contact.faq_a3': 'Please call our 24/7 Rescue Hotline immediately (0905 888 999). Our mobile technical team will arrive in 15–25 minutes for tire patching, battery jump-start, or replacement vehicle completely free.',
    'contact.faq_q4': 'Which channel is best for international tourists (English, Russian, Korean) to contact us?',
    'contact.faq_a4': 'International guests can chat directly on WhatsApp (+84 905 888 999) or Zalo OA. Our multilingual staff fluent in English, Russian, and Korean will guide you regarding IDP permits and local rules.',
