    'guide.faq_title': 'Частые вопросы о процессе аренды',
    'guide.faq_desc': 'Ответы о ночной доставке, отмене бронирования, документах и техпомощи',
    'guide.faq_q1': 'Могу ли я получить авто ночью в аэропорту Камрань (после 22:00)?',
    'guide.faq_a1': 'Да, конечно! Nha Trang Car осуществляет доставку авто круглосуточно 24/7 в зал прилета аэропорта Камрань. Просто укажите номер рейса при бронировании; наш сотрудник встретит вас с табличкой без ночных доплат.',
    'guide.faq_q2': 'Что происходит с депозитом 20% в случае переноса или отмены рейса?',
    'guide.faq_a2': 'Полное спокойствие! Nha Trang Car гарантирует 100% возврат депозита бронирования при отмене за 24 часа. В случае задержки рейса мы бесплатно перенесем время подачи машины к фактическому времени посадки.',
    'guide.faq_q3': 'Оставляет ли компания оригиналы паспорта или прав себе?',
    'guide.faq_a3': 'Категорически НЕТ! Мы уважаем конфиденциальность гостей. Наш сотрудник лишь делает фото/скан на месте для сверки и сразу возвращает все оригиналы документов.',
    'guide.faq_q4': 'Как и когда возвращается гарантийный залог при сдаче авто?',
    'guide.faq_a4': 'Возврат залога занимает всего 3-5 минут. Сразу после сверки состояния авто с исходным актом 360° компания возвращает 100% залога переводом 24/7 или наличными.',
    'guide.faq_q5': 'Что делать, если пробило колесо или возникла поломка в дороге?',
    'guide.faq_a5': 'Просто позвоните на горячую линию техпомощи 24/7 (0905 888 999). Наша выездная бригада прибудет за 15-30 минут в любую точку Нячанга или пляжа Бай Дай Камрань.',
    'guide.faq_q6': 'Есть ли ограничение пробега (км) в день?',
    'guide.faq_a6': 'Для мотоциклов и электроскутеров пробег по всей провинции Кханьхоа неограничен. Для легковых авто действует комфортный лимит 300 - 350 км/день (достаточно для поездок в Виньхи, Доклет или Далат без доплат).',
