    'home.faq_a1': '필요 서류: 1. 여권; 2. 1968년 비엔나 협약 국제운전면허증(한국 면허증 원본 동시 지참; 전기 스쿠터는 면허 불필요); 3. 계약 보증금 (차량 반납 시 100% 즉시 환불).',
