    'guide.faq_title': '렌터카 대여 절차 자주 묻는 질문',
    'guide.faq_desc': '심야 배차, 항공편 취소, 서류 보관 여부 및 긴급 출동 서비스 상세 안내',
    'guide.faq_q1': '깜라인 공항에 심야(22시 이후) 도착하는 경우에도 차량 수령이 가능한가요?',
    'guide.faq_a1': '네, 가능합니다! 나트랑 카는 깜라인 국제공항 입국장에서 24시간 배차 서비스를 지원합니다. 온라인 예약 시 항공편명을 남겨주시면 담당 직원이 실제 착륙 시간을 조회하여 추가 심야 할증 없이 입국장에서 네임보드로 맞이합니다.',
    'guide.faq_q2': '항공편이 변경되거나 여행이 취소되는 경우 20% 예약금은 어떻게 처리되나요?',
    'guide.faq_a2': '안심하셔도 좋습니다! 픽업 24시간 전 취소 시 24시간 실시간 계좌이체로 예약금 100%를 즉시 환불해 드립니다. 항공편 지연 시에는 변경된 착륙 시간에 맞춰 추가 비용 없이 무료로 배차 시간을 변경해 드립니다.',
    'guide.faq_q3': '대여 기간 동안 주민등록증이나 여권 원본을 업체에서 보관하나요?',
    'guide.faq_a3': '절대 보관하지 않습니다! 고객님의 개인정보를 철저히 존중하며, 현장에서 담당 직원이 신분증을 확인 및 사진 스캔한 후 여권, 면허증 등 모든 원본 서류를 즉시 고객님께 돌려드립니다.',
    'guide.faq_q4': '차량 반납 시 보증금은 어떤 방식으로 얼마나 걸려 환급되나요?',
    'guide.faq_a4': '보증금 환급은 3~5분 내로 신속히 진행됩니다. 담당 직원이 초기 360° 점검표와 대조하여 차량 이상 유무를 확인한 즉시, 고객님의 희망에 따라 24/7 실시간 계좌이체 또는 현금으로 보증금 100%를 현장에서 즉시 반환해 드립니다.',
    'guide.faq_q5': '운행 중 타이어 펑크나 차량 이상 등 긴급 상황이 발생하면 어떻게 해야 하나요?',
    'guide.faq_a5': '24시간 긴급 출동 콜센터(0905 888 999)로 즉시 연락해 주세요. 나트랑 카 긴급 출동팀이 나트랑 시내 및 바이자이 해안 도로 전역 어디든 15~30분 이내에 현장에 도착하여 타이어 교체, 배터리 충전 또는 동급 차량 교체를 지원합니다.',
    'guide.faq_q6': '일일 주행거리(km) 제한이 있나요?',
    'guide.faq_a6': '오토바이와 전동스쿠터는 카인호아성 전역에서 무제한입니다. 렌터카는 일일 300~350km의 넉넉한 기준이 제공됩니다 (빈히만, 독렛, 달랏 여행에도 충분합니다).',
