    // Contact FAQ Accordion
    'contact.faq_badge': '자주 묻는 질문 (FAQ)',
    'contact.faq_title': '문의 및 차량 픽업 관련 FAQ',
    'contact.faq_desc': 'DriveRent 나트랑 차량 예약 및 상담 시 여행객들이 가장 자주 문의하시는 질문입니다.',
    'contact.faq_q1': '심야 시간(밤 22시 이후)에도 깜란 공항에서 차량 인수가 가능한가요?',
    'contact.faq_a1': '네, 가능합니다. 깜란 국제공항 도착 터미널에 24시간 전담 직원이 상주하고 있습니다. 항공편명과 도착 예정 시간을 알려주시면 공항 주차장에 차량을 미리 대기시켜 놓습니다.',
    'contact.faq_q2': '나트랑 시내 호텔이나 리조트 로비까지 배차가 되나요?',
    'contact.faq_a2': '네, 1일 이상 렌트하시는 모든 고객님께 나트랑 시내 전 지역 호텔 및 쩐푸 해변 도로변 숙소까지 100% 무료로 차량을 직접 가져다 드리고 반납도 받아드립니다.',
    'contact.faq_q3': '주행 중 타이어 펑크나 고장이 발생하면 어떻게 지원받나요?',
    'contact.faq_a3': '즉시 24시간 긴급 출동 핫라인(0905 888 999)으로 전화해 주세요. 15~25분 이내에 현장 정비팀이 출동하여 펑크 수리, 점프 스타트 또는 무상 대차를 진행해 드립니다.',
    'contact.faq_q4': '외국인 관광객은 어떤 채널로 상담하는 것이 가장 편리한가요?',
    'contact.faq_a4': '해외 여행객은 WhatsApp(+84 905 888 999) 또는 Zalo 메신저를 통해 편리하게 대화하실 수 있습니다. 영어 및 한국어 상담이 지원되며 국제운전면허증 규정도 상세히 안내해 드립니다.',
