    'reg.faq_a1': '네, 가능합니다! 승용차 자가운전은 여권과 1968 비엔나 국제운전면허증(본국 원본 면허증 포함)만 있으면 됩니다. 오토바이는 비엔나 A종 면허증이 있거나, 스마트 전기 스쿠터의 경우 면허가 전혀 필요 없습니다 (베트남 법률상 100% 합법).',
    'reg.faq_q2': '스마트 전기 스쿠터와 50cc 미만 차량은 정말 운전면허가 필요 없나요?',
    'reg.faq_a2': '100% 사실입니다! 베트남 도로교통법 규정상 모터 출력 4kW 미만의 전기 스쿠터 또는 50cc 미만 원동기 장치 자전거는 운전면허가 필요하지 않습니다. 만 16세 이상 및 외국인 관광객 누구나 나트랑 전역에서 자유롭게 운행하실 수 있습니다.',
